rows = []
for line in data.strip().split("\n"):
    if not line.strip():
        continue
    parts = line.split("\t")
    table_name = parts[0].strip()
    columns = parts[1].strip().split(",")
    for col in columns:
        rows.append([table_name, col.strip()])

with open("table_columns.csv", "w", newline="") as f:
    writer = csv.writer(f)
    writer.writerow(["table_name", "column_name"])
    writer.writerows(rows)

print(f"Done! {len(rows)} rows written to table_columns.csv")
